// Test: traitUseNotExtended
namespace PsalmTest_template_trait_template_1 {
    /**
     * @template T
     */
    trait CollectionTrait
    {
        /**
         * @return array<T>
         */
        abstract function elements() : array;

        /**
         * @return T|null
         */
        public function first()
        {
            return $this->elements()[0] ?? null;
        }
    }

    class Service
    {
        /**
         * @use CollectionTrait<int>
         */
        use CollectionTrait;

        /**
         * @return array<int>
         */
        public function elements(): array
        {
            return [1, 2, 3, 4];
        }
    }

    assertType('int|null', (new Service())->first());
    assertType('array<int>', (new Service())->elements());
}

// Test: extendedTraitUse
namespace PsalmTest_template_trait_template_2 {
    /**
     * @template T
     */
    trait CollectionTrait
    {
        /**
         * @return array<T>
         */
        abstract function elements() : array;

        /**
         * @return T|null
         */
        public function first()
        {
            return $this->elements()[0] ?? null;
        }
    }

    /**
     * @template TValue
     */
    trait BridgeTrait
    {
        /**
         * @use CollectionTrait<TValue>
         */
        use CollectionTrait;
    }

    class Service
    {
        /**
         * @use BridgeTrait<int>
         */
        use BridgeTrait;

        /**
         * @return array<int>
         */
        public function elements(): array
        {
            return [1, 2, 3, 4];
        }
    }

    assertType('int|null', (new Service())->first());
}

