// Test: traitSelfAsParam
namespace PsalmTest_template_trait_template_12 {
    trait InstancePool {
        /**
         * @template T as self
         * @param callable():?T $callback
         * @return ?T
         */
        public static function getInstance(callable $callback)
        {
            return $callback();
        }
    }

    class Foo
    {
        use InstancePool;
    }

    assertType('Foo|null', Foo::getInstance(function () {
        return new Foo();
    }));
}

// Test: possiblyNullReferenceOnTraitDefinedMethod
namespace PsalmTest_template_trait_template_13 {
    class Item {}

    /**
     * @template TKey as array-key
     * @template TValue
     */
    trait T1 {
        /**
         * @var array<TKey, TValue>
         */
        protected $mocks = [];

        /**
         * @param TKey $offset
         * @return TValue|null
         */
        public function offsetGet($offset) {
            return $this->mocks[$offset] ?? null;
        }
    }

    /**
     * @template TKey as array-key
     * @template TValue
     */
    interface Arr {
        /**
         * @param TKey $offset
         * @return TValue|null
         */
        public function offsetGet($offset);
    }

    /**
     * @template TKey as array-key
     * @template TValue
     * @implements Arr<TKey, TValue>
     */
    class C implements Arr {
        /** @use T1<TKey, TValue> */
        use T1;
    }

    /** @param C<string, Item> $c */
    function test(C $c): void {
        assertType('Item|null', $c->offsetGet('a'));
    }
}
